}

# Convert string times to minutes and sort
for person in schedule:
    for day in schedule[person]:
        schedule[person][day] = sorted(
            [(to_minutes(s), to_minutes(e)) for s, e in schedule[person][day]],
            key=lambda x: x[0]
        )

meeting_duration = 60  # minutes
work_days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
# Preference order: avoid Monday if possible
preference = ["Tuesday", "Wednesday", "Thursday", "Friday", "Monday"]

answer = None
for day in preference:
    brian_busy = schedule["Brian"].get(day, [])
    julia_busy = schedule["Julia"].get(day, [])
    brian_free = complement(brian_busy)
    julia_free = complement(julia_busy)
    for s, e in intersect(brian_free, julia_free):
        if e - s >= meeting_duration:
            start = s
            end = s + meeting_duration
            answer = [day, to_time(start), to_time(end)]
            break
    if answer:
