Lisa has blocked their calendar on Monday during 9:30 to 10:30, 11:00 to 11:30, 12:00 to 12:30, 13:00 to 13:30, 14:00 to 14:30, 16:00 to 17:00; 

Find a time that works for everyone's schedule and constraints. 
SOLUTION:

DAYS = ["Monday", "Tuesday", "Wednesday"]

WORK_START_MIN = 9 * 60
WORK_END_MIN = 17 * 60
MEETING_DURATION_MIN = 60


def parse_time(time_str):
    hours, minutes = map(int, time_str.split(":"))
    return hours * 60 + minutes


def format_time(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


CALENDARS = {
    "Patrick": {day: [] for day in DAYS},
    "Roy": {
        "Monday": [
            ("10:00", "11:30"),
            ("12:00", "13:00"),
            ("14:00", "14:30"),
            ("15:00", "17:00"),
        ],
        "Tuesday": [
            ("10:30", "11:30"),
            ("12:00", "14:30"),
            ("15:00", "15:30"),
            ("16:00", "17:00"),
        ],
        "Wednesday": [
            ("09:30", "11:30"),
            ("12:30", "14:00"),
            ("14:30", "15:30"),
            ("16:30", "17:00"),
        ],
    },
}

PARTICIPANTS = ["Patrick", "Roy"]

BUSY_MINUTES = {
    person: {
        day: sorted(
            (parse_time(start), parse_time(end))
            for start, end in CALENDARS[person][day]
        )
        for day in DAYS
    }
    for person in PARTICIPANTS
}


def is_free(person, day, start_min, end_min):
    for busy_start, busy_end in BUSY_MINUTES[person][day]:
        if start_min < busy_end and busy_start < end_min:
            return False
    return True


def main():
    for day in DAYS:
        for start_min in range(
            WORK_START_MIN, WORK_END_MIN - MEETING_DURATION_MIN + 1
        ):
            end_min = start_min + MEETING_DURATION_MIN
            if all(
                is_free(person, day, start_min, end_min)
                for person in PARTICIPANTS
            ):
                print([day, format_time(start_min), format_time(end_min)])
                return


if __name__ == "__main__":
    main()

